/// <summary>
/// Everything a native module needs to work on a device another library owns: the contract version, the function
/// table and the instance / adapter / device / queue handles. Filled from any IWebGpuDeviceSource.
/// The handles are BORROWED: valid while the owner keeps its device (until the owner is disposed); reading them
/// takes no reference. A module that keeps a handle longer calls its *AddRef and later *Release on it.
/// </summary>
/// <remarks>C type: <c>WGPUCodebrixDeviceHandoff</c> (include/codebrix_wgpu_procs.h in the package); Rust: include/codebrix_wgpu_procs.rs.</remarks>
[StructLayout(LayoutKind.Sequential)]
public unsafe partial struct CodebrixDeviceHandoff
{
    /// <summary>The layout version this binding writes (<c>WGPU_CODEBRIX_DEVICE_HANDOFF_VERSION</c>).</summary>
    public const uint CurrentVersion = 1u;

    /// <summary>Set in flags when the device has an uncaptured-error handler (errors no scope catches are reported, not fatal). (<c>WGPU_CODEBRIX_DEVICE_HANDOFF_FLAG_UNCAPTURED_ERROR_HANDLER</c>)</summary>
    public const uint FlagUncapturedErrorHandler = 1u;

    /// <summary>sizeof(WGPUCodebrixDeviceHandoff) as filled by the producer.</summary>
    public uint Size;

    /// <summary>The layout version of this struct (WGPU_CODEBRIX_DEVICE_HANDOFF_VERSION).</summary>
    public uint Version;

    /// <summary>WGPU_CODEBRIX_API_VERSION of the loaded library; refuse the hand-off when it differs from the one the module was built against.</summary>
    public uint ApiVersion;

    /// <summary>The backend the device runs on (WGPUBackendType_Undefined without a device).</summary>
    public BackendType Backend;

    /// <summary>Bit WGPU_CODEBRIX_DEVICE_HANDOFF_FLAG_UNCAPTURED_ERROR_HANDLER: the device has an uncaptured-error handler. Without it any uncaptured validation error ENDS THE PROCESS - keep risky work inside error scopes.</summary>
    public uint Flags;

    /// <summary>Zero.</summary>
    public uint Reserved;

    /// <summary>The function table of the loaded library (process lifetime; never free it).</summary>
    public CodebrixProcTable* Procs;

    /// <summary>The instance, or NULL when the owner has none.</summary>
    public Instance Instance;

    /// <summary>The adapter, or NULL when the owner has none.</summary>
    public Adapter Adapter;

    /// <summary>The device; NULL means no usable device.</summary>
    public Device Device;

    /// <summary>The queue the owner submits to.</summary>
    public Queue Queue;
}

/// <summary>
/// One frame's target for a native module: the texture another library owns (IWebGpuTextureTarget) and the
/// command encoder of its open pass.
/// The handles are BORROWED for the pass only (from BeginWebGpuPass to EndWebGpuPass): record every command that
/// touches the texture into commandEncoder, on the thread that opened the pass, close your own render / compute
/// passes before returning, and never finish, submit or release the encoder.
/// </summary>
/// <remarks>C type: <c>WGPUCodebrixFrameHandoff</c> (include/codebrix_wgpu_procs.h in the package); Rust: include/codebrix_wgpu_procs.rs.</remarks>
[StructLayout(LayoutKind.Sequential)]
public unsafe partial struct CodebrixFrameHandoff
{
    /// <summary>The layout version this binding writes (<c>WGPU_CODEBRIX_FRAME_HANDOFF_VERSION</c>).</summary>
    public const uint CurrentVersion = 1u;

    /// <summary>sizeof(WGPUCodebrixFrameHandoff) as filled by the producer.</summary>
    public uint Size;

    /// <summary>The layout version of this struct (WGPU_CODEBRIX_FRAME_HANDOFF_VERSION).</summary>
    public uint Version;

    /// <summary>The texture's format (pipelines must target it).</summary>
    public TextureFormat Format;

    /// <summary>The width in pixels.</summary>
    public uint Width;

    /// <summary>The height in pixels.</summary>
    public uint Height;

    /// <summary>The texture's sample count (pipelines and depth attachments must match).</summary>
    public uint SampleCount;

    /// <summary>The texture's usage flags.</summary>
    public TextureUsage Usage;

    /// <summary>The texture.</summary>
    public Texture Texture;

    /// <summary>A default view of the texture (a render attachment).</summary>
    public TextureView TextureView;

    /// <summary>The encoder of the open pass (from BeginWebGpuPass); NULL when no pass is open - then record nothing.</summary>
    public CommandEncoder CommandEncoder;
}
